// CSD_RATIONALE_BEGIN
// This strategy follows a two-phase approach for solving math word problems step-by-step.
// Phase 1: Unconstrained reasoning where we generate tokens without grammar constraints.
//         We penalize the end-of-sequence token (<<) to encourage longer chains.
//         If we encounter a start-of-sequence token (<<), we transition to the constrained phase.
// Phase 2: Constrained reasoning where we generate tokens within grammar constraints.
//         We monitor for the end-of-sequence token (>>) and exit the constrained phase when encountered.
//         We also track dead-end situations and exit the constrained phase if the grammar becomes too narrow.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    lm.GenerateLogits(prompt + generated);
    helpers.PenalizeTokenLogits(lm, [">>"], 5.0);
    var next := lm.ChooseNextTokenUnconstrained();
    helpers.cost := helpers.cost + 1;
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if next == "<<" {
      insideConstrained := true;
      currentConstrained := [];
    }
  } else {
    var narrow := helpers.DeadEndDetection(parser, currentConstrained, 2);
    if parser.IsCompletePrefix(currentConstrained) || narrow {
      insideConstrained := false;
    } else {
      var next, isValid := helpers.SoftConstrainedStep(lm, parser, prompt, currentConstrained, 6.0);
      generated := generated + [next];
      steps := steps + 1;
      if isValid {
        currentConstrained := currentConstrained + [next];
        if next == ">>" { insideConstrained := false; }
      } else {
        insideConstrained := false;
      }
    }
  }
}
cost := helpers.cost;

